package com.grifplot.libros;
import android.app.*;import android.content.*;import android.net.*;import android.graphics.*;import android.webkit.*;import android.widget.*;import java.util.*;import java.io.*;import java.util.concurrent.atomic.*;import org.json.*;
/** Google Images browser: tapping marks a selection; packaging uses public image URLs. */
final class ImageBrowser extends LinearLayout {
 final MainActivity a;final WebView web;final EditText input;final TextView count,status;final LinkedHashMap<String,ImagePack.Item> selected=new LinkedHashMap<>();volatile boolean closed=false;boolean preparing=false;final AtomicBoolean cancelled=new AtomicBoolean(false);
 ImageBrowser(MainActivity act){super(act);a=act;setOrientation(VERTICAL);LinearLayout search=a.row();input=new EditText(a);input.setSingleLine(true);input.setHint("¿Qué imágenes estás buscando?");input.setTextSize(26);LargeKeyboard.bind(a,input,()->search(),false);search.addView(input,new LayoutParams(0,a.dp(80),1));search.addView(a.button("Buscar",v->search(),true));addView(search);status=a.label("Toca imágenes para seleccionarlas. Se descargará el original cuando Google muestre su enlace; en caso contrario, se conservará el enlace disponible.",17,MainActivity.MUTED);addView(status);count=a.label("0 imágenes seleccionadas",20,MainActivity.RED);addView(count);web=new WebView(a);WebSettings settings=web.getSettings();settings.setJavaScriptEnabled(true);settings.setDomStorageEnabled(true);settings.setAllowFileAccess(false);settings.setAllowContentAccess(false);settings.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);settings.setSafeBrowsingEnabled(true);android.webkit.CookieManager.getInstance().setAcceptThirdPartyCookies(web,false);web.setWebViewClient(new WebViewClient(){public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){String u=r.getUrl().toString();if(u.startsWith("grifplot-image://select")){if(google(v.getUrl()))select(r.getUrl().getQueryParameter("data"));return true;}if(!r.isForMainFrame())return false;if(!google(u)){a.toast("Toca una imagen para seleccionarla; la selección no abre la página de origen.");return true;}return false;}public void onPageFinished(WebView v,String url){if(google(url))install();}public void onReceivedError(WebView v,WebResourceRequest r,WebResourceError e){if(r.isForMainFrame())status.setText("No se pudo cargar Google. Revisa internet y repite la búsqueda.");}public void onReceivedSslError(WebView v,SslErrorHandler h,android.net.http.SslError e){h.cancel();a.toast("Conexión de la fuente no válida");}});web.setOnTouchListener((v,e)->{a.touch();return false;});web.setOnLongClickListener(v->true);addView(web,new LayoutParams(-1,0,1));LinearLayout bottom=a.row();bottom.addView(a.button("Ver selección",v->selection(),false),new LayoutParams(0,a.dp(60),1));bottom.addView(a.button("Enviar por WhatsApp",v->send(),true),new LayoutParams(0,a.dp(60),1));bottom.addView(a.button("Finalizar visita",v->finish(),false),new LayoutParams(0,a.dp(60),1));addView(bottom);web.loadData("<html><body style='font-family:sans-serif;text-align:center;padding:40px'><h2>Busca imágenes en Google</h2><p>Escribe arriba y toca Buscar. Después toca cada imagen que quieras seleccionar.</p></body></html>","text/html","UTF-8");}
 static boolean google(String u){try{Uri uri=Uri.parse(u);String h=uri.getHost();return "https".equals(uri.getScheme())&&h!=null&&(h.equals("www.google.com")||h.equals("google.com")||h.equals("consent.google.com"));}catch(Exception e){return false;}}
 void search(){String q=input.getText().toString().trim();if(q.isEmpty())return;if(!a.online()){a.message("Sin conexión","La búsqueda de imágenes en Google necesita internet.");return;}a.hideKeyboard();status.setText("Toca para seleccionar o quitar una imagen. Tu selección se conserva al cambiar la búsqueda.");web.loadUrl("https://www.google.com/search?tbm=isch&q="+Uri.encode(q));}
 void install(){try{InputStream in=a.getAssets().open("image-selection.js");ByteArrayOutputStream bytes=new ByteArrayOutputStream();byte[] buf=new byte[4096];int n;while((n=in.read(buf))!=-1)bytes.write(buf,0,n);in.close();web.evaluateJavascript(new String(bytes.toByteArray(),"UTF-8"),null);sync();}catch(Exception e){a.toast("No se pudo activar la selección. Recarga la búsqueda.");}}
 void select(String json){if(closed||json==null||json.length()>1000000)return;try{JSONObject value=new JSONObject(json);String url=value.optString("url"),source=value.optString("source"),title=value.optString("title","Imagen");if(!url.startsWith("https://"))url="";if(!source.startsWith("https://"))source="";if(url.isEmpty()&&source.isEmpty()&&value.optString("google").isEmpty()){a.toast("Google no ofrece un enlace para esta imagen. Prueba otra.");return;}ImagePack.Item item=new ImagePack.Item(url,source,title.length()>300?title.substring(0,300):title);item.original=value.optString("original",item.original);if(!item.original.startsWith("https://"))item.original="";item.google=value.optString("google",item.google);if(!(item.google.startsWith("https://")||item.google.matches("(?is)^data:image/(png|jpeg|gif|webp);base64,.*"))||item.google.length()>350000)item.google="";item.stable=value.optString("key");if(item.stable.length()>1000)item.stable="";if(selected.containsKey(item.key()))selected.remove(item.key());else if(selected.size()<100)selected.put(item.key(),item);else a.toast("Puedes seleccionar hasta 100 imágenes por envío");count.setText(selected.size()+" imágenes seleccionadas");a.touch();sync();}catch(Exception ignored){}}
 void sync(){JSONArray keys=new JSONArray();for(String key:selected.keySet())keys.put(key);web.evaluateJavascript("window.grifplotKeys="+keys.toString()+";if(window.grifplotPaint)window.grifplotPaint();",null);}
 void selection(){if(selected.isEmpty()){a.toast("Primero toca las imágenes que deseas enviar");return;}ArrayList<ImagePack.Item> list=new ArrayList<>(selected.values());String[] names=new String[list.size()];for(int i=0;i<names.length;i++)names[i]=(i+1)+". "+list.get(i).title+"\n"+(list.get(i).original.isEmpty()?"Original por buscar; Google como respaldo":"Original detectado: "+list.get(i).original);new AlertDialog.Builder(a).setTitle("Selección · Toca para quitar").setItems(names,(d,i)->{selected.remove(list.get(i).key());count.setText(selected.size()+" imágenes seleccionadas");sync();}).setPositiveButton("Enviar por WhatsApp",(d,w)->send()).setNegativeButton("Volver",null).show();}
 void finish(){new AlertDialog.Builder(a).setTitle("Finalizar visita").setItems(new String[]{"Enviar imágenes por WhatsApp","Luego lo imprimiré, gracias"},(d,w)->{if(w==0)send();else a.endVisit();}).setNegativeButton("Continuar",null).show();}
 void send(){if(preparing)return;if(selected.isEmpty()){a.toast("Selecciona al menos una imagen");return;}preparing=true;JSONArray keys=new JSONArray();for(String key:selected.keySet())keys.put(key);web.evaluateJavascript("typeof window.grifplotSelectionInfo==='function'?window.grifplotSelectionInfo("+keys+"):[]",value->{preparing=false;if(closed||!a.screen.equals("images"))return;try{JSONArray list=new JSONArray(value);for(int i=0;i<list.length();i++){JSONObject info=list.getJSONObject(i);ImagePack.Item item=selected.get(info.optString("key"));if(item!=null){String original=info.optString("original"),source=info.optString("source");if(original.startsWith("https://")){item.original=original;item.url=original;}if(source.startsWith("https://"))item.source=source;}}}catch(Exception ignored){}prepareSend();});}
 void prepareSend(){if(preparing)return;if(selected.isEmpty()){a.toast("Selecciona al menos una imagen");return;}String target=null;for(String pkg:new String[]{"com.whatsapp","com.whatsapp.w4b"})try{a.getPackageManager().getPackageInfo(pkg,0);target=pkg;break;}catch(Exception ignored){}if(target==null){a.message("WhatsApp no está instalado","Instala o configura WhatsApp en la tablet para compartir el paquete. Grifplotlibros no pide credenciales.");return;}final String pkg=target,ua=web.getSettings().getUserAgentString();final ArrayList<ImagePack.Item> list=new ArrayList<>(selected.values());final int token=a.generation;cancelled.set(false);preparing=true;TextView progress=a.label("Preparando 0 de "+list.size()+" imágenes…",20,MainActivity.INK);AlertDialog dialog=new AlertDialog.Builder(a).setTitle("Preparar ZIP para WinRAR").setView(progress).setNegativeButton("Cancelar",(d,w)->cancelled.set(true)).setCancelable(false).create();dialog.show();a.io.execute(()->{try{ImagePack.Result result=ImagePack.create(list,new File(a.getCacheDir(),"shares"),ua,new ImagePack.Progress(){String stage="Preparando imágenes…";public boolean cancelled(){return cancelled.get()||closed||a.generation!=token;}public String dimensions(File file){BitmapFactory.Options options=new BitmapFactory.Options();options.inJustDecodeBounds=true;BitmapFactory.decodeFile(file.toString(),options);return options.outWidth>0?options.outWidth+" × "+options.outHeight+" píxeles":"No disponible";}public void bytes(long count,long total){String text=stage+String.format(Locale.ROOT,"\n%.1f MB",count/1048576.0);a.ui.post(()->{if(dialog.isShowing()){progress.setText(text);a.touch();}});}public void phase(String text){stage=text;a.ui.post(()->{if(dialog.isShowing()){progress.setText(text);a.touch();}});}public void update(int done,int total){a.ui.post(()->{progress.setText("Preparando "+done+" de "+total+" imágenes…");a.touch();});}});a.ui.post(()->{dialog.dismiss();preparing=false;if(closed||a.generation!=token||cancelled.get()){result.file.delete();return;}new AlertDialog.Builder(a).setTitle(result.downloaded>0?"ZIP preparado":"Enlaces TXT preparados").setMessage(result.originals+" originales, "+result.previews+" respaldos de Google y "+result.failed+" sin descargar. "+(result.downloaded>0?"El ZIP incluye calidad-imagenes.txt con la resolución y el tipo de cada archivo; se abre con WinRAR.":"La fuente no permitió descargar estas imágenes. Se enviarán los enlaces en TXT.")+"\nDestino: +51 952 628 844. Confirma el archivo y el destinatario en WhatsApp.").setPositiveButton("Abrir WhatsApp",(d,w)->share(result,pkg)).setNegativeButton("Volver",null).show();});}catch(Exception e){a.ui.post(()->{dialog.dismiss();preparing=false;if(!closed&&!cancelled.get()&&a.generation==token)a.message("No se pudo preparar el paquete","Revisa el espacio de la tablet y repite. "+e.getMessage());});}});}
 void share(ImagePack.Result result,String pkg){Uri uri=Uri.parse("content://"+a.getPackageName()+".libros.share/share/"+result.file.getName());Intent send=new Intent(Intent.ACTION_SEND);send.setType(result.file.getName().endsWith(".zip")?"application/zip":"text/plain");send.setPackage(pkg);send.putExtra("jid","51952628844@s.whatsapp.net");send.putExtra(Intent.EXTRA_STREAM,uri);send.putExtra(Intent.EXTRA_TEXT,"Imágenes para impresión: "+result.originals+" originales, "+result.previews+" respaldos de Google, "+result.failed+" enlaces pendientes. Destino: +51 952 628 844");send.setClipData(ClipData.newRawUri("Imágenes y enlaces",uri));send.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);try{a.grantUriPermission(pkg,uri,Intent.FLAG_GRANT_READ_URI_PERMISSION);a.startActivity(send);a.endVisit();}catch(Exception e){a.message("No se pudo abrir WhatsApp","Revisa que WhatsApp permita adjuntar el archivo en esta tablet.");}}
 void close(){if(closed)return;closed=true;cancelled.set(true);selected.clear();web.stopLoading();web.loadUrl("about:blank");web.destroy();android.webkit.CookieManager.getInstance().removeAllCookies(null);WebStorage.getInstance().deleteAllData();}
}
